    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      asanaAccessToken: 'test-token',
      asanaWorkspaceGid: '1234567890123456',
      fetch,
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as JotformSubmissionPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.taskId).toBe('9876543210987654')
    expect(result.taskName).toBe('John Doe Acme Corp')
  })
})

