export interface JotformSubmissionPayload {
  answers: Record<string, string>
}

export interface AsanaTaskResponse {
  gid: string
  name: string
  notes: string
  resource_type: string
}

export interface HandleResult {
  taskId: string
  taskName: string
}

function getFetch(config: ConnectorConfig): typeof fetch {
  return config.fetch ?? fetch
}

function validatePayload(payload: unknown): JotformSubmissionPayload {
  if (!payload || typeof payload !== 'object') {
    throw new Error('Invalid payload: expected an object')
  }
  const p = payload as Record<string, unknown>
  if (!p.answers || typeof p.answers !== 'object') {
    throw new Error('Missing required field: answers')
  }
  const answers = p.answers as Record<string, string>
  return { answers }
}

function formatTaskName(answers: Record<string, string>): string {
  const parts: string[] = []
  if (answers.first_name) parts.push(answers.first_name)
  if (answers.last_name) parts.push(answers.last_name)
  if (answers.company) parts.push(answers.company)
  return parts.length > 0 ? parts.join(' ') : 'Jotform Submission'
}

function formatNotes(answers: Record<string, string>): string {
  return Object.entries(answers)
    .map(([key, value]) => `${key}: ${value}`)
    .join('\n')
}

export async function handle(
  payload: unknown,
  config: ConnectorConfig
): Promise<HandleResult> {
  const submission = validatePayload(payload)
  const { answers } = submission

  const taskName = formatTaskName(answers)
  const notes = formatNotes(answers)

  const requestBody = {
    data: {
      workspace: config.asanaWorkspaceGid,
      name: taskName,
      notes,
    },
  }

  const fetchFn = getFetch(config)
  const response = await fetchFn('https://app.asana.com/api/1.0/tasks', {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.asanaAccessToken}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(requestBody),
  })

  if (!response.ok) {
    throw new Error(`Asana API error: ${response.status} ${response.statusText} at POST https://app.asana.com/api/1.0/tasks`)
  }

  const result = (await response.json()) as { data: AsanaTaskResponse }
  return {
    taskId: result.data.gid,
    taskName: result.data.name,
  }
}

